impl Solution {
    pub fn find_judge(n: i32, trust: Vec<Vec<i32>>) -> i32 {
        let mut cnt1 = vec![0; (n + 1) as usize];
        let mut cnt2 = vec![0; (n + 1) as usize];

        for t in trust.iter() {
            let a = t[0] as usize;
            let b = t[1] as usize;
            cnt1[a] += 1;
            cnt2[b] += 1;
        }

        for i in 1..=n as usize {
            if cnt1[i] == 0 && cnt2[i] == (n as usize) - 1 {
                return i as i32;
            }
        }

        -1
    }
}

class Solution:
    def findJudge(self, n: int, trust: List[List[int]]) -> int:
        if n == 1 and len(trust) == 0:
            return 1
        dic = {}
        values = set()
        for i in trust:
            values.add(i[0])
            if i[1] in dic:
                dic[i[1]].append(i[0])
            else: dic[i[1]] = [i[0]]

        for key, value in dic.items():
            if len(dic[key]) == n-1 and key not in values:
                return key
        return -1

class Solution {
public:
    int findJudge(int N, vector<vector<int>>& trust) {
        int sum  = N*(N+1)/2;
        int trusts[N + 1], trustedBy[N + 1];
        for (int i = 1; i < N + 1; i++) {
            trusts[i] = 0;
            trustedBy[i] = 0;
        }
        for (int i = 0; i < trust.size(); i++) {
            trusts[trust[i][0]] += trust[i][1];
            trustedBy[trust[i][1]] += trust[i][0];
        }
        for (int i = 1; i < N + 1; i++) {
            if (trusts[i] == 0) {
                if (sum - trustedBy[i] == i) {
                    return i;
                }
            }
        }
        return -1;
    }
};

